    """fq 同款 effect：未登记或窗口 [a,z) 外为 N；窗口内 D 为 D、F 按
    ((now-a)//v)%2=0 相位取 D 否则 N、S 为 S。"""
    if fault is None or not fault[1] <= now < fault[2]:
        return "N"
    k, a, _, v = fault
    if k == "D":
